import json
from pathlib import Path
from unittest.mock import patch
import numpy as np
import torch
from examples.huggingface import mlx_validation as validation
from examples.huggingface.reference_trajectory import reference_parameters

captured={}; records={'actual':[], 'reference':[]}
original_prepare=validation.prepare
original_step=torch.optim.AdamW.step

def prepare(*args,**kwargs):
    model,reference=original_prepare(*args,**kwargs)
    captured.update(model=model,reference=reference)
    return model,reference

def step(optimizer,*args,**kwargs):
    model,reference=captured['model'],captured['reference']
    actual=dict(zip(model.onnx.names,model.onnx.adapters,strict=True))
    is_actual=optimizer.param_groups[0]['params'][0] is next(iter(actual.values()))
    params=actual if is_actual else reference_parameters(model,reference)
    label='actual' if is_actual else 'reference'
    before={name:{'parameter_before':p.detach().numpy().copy(), 'gradient':p.grad.detach().numpy().copy(),
                  'exp_avg_before':optimizer.state[p].get('exp_avg',torch.zeros_like(p)).detach().numpy().copy(),
                  'exp_avg_sq_before':optimizer.state[p].get('exp_avg_sq',torch.zeros_like(p)).detach().numpy().copy()}
            for name,p in params.items()}
    result=original_step(optimizer,*args,**kwargs)
    for name,p in params.items():
        before[name].update(parameter_after=p.detach().numpy().copy(),
                            exp_avg_after=optimizer.state[p]['exp_avg'].numpy().copy(),
                            exp_avg_sq_after=optimizer.state[p]['exp_avg_sq'].numpy().copy())
    records[label].append(before)
    return result

with patch.object(validation,'prepare',prepare),patch.object(torch.optim.AdamW,'step',step):
